 // Wait only for the unused portion of the visual transition. Cancellation stays responsive.
 async function thinkingBeat(started, signal) {
  signal.throwIfAborted();
  if (matchMedia('(prefers-reduced-motion: reduce)').matches) return;
  const remaining = 720 - (Date.now() - started);
  if (remaining <= 0) return;
  await new Promise((resolve, reject) => {
   const timer = setTimeout(() => { signal.removeEventListener('abort', cancel); resolve(); }, remaining);
   function cancel() { clearTimeout(timer); reject(signal.reason); }
   signal.addEventListener('abort', cancel, { once: true });
  });
 }
